<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {RouterLink} from 'vue-router'
import api from '@/api/client'
const current=ref(''),next=ref(''),confirm=ref(''),message=ref(''),busy=ref(false)
const policyLoading=ref(true)
const prefixes=ref(''),smsLimit=ref(20),policyMessage=ref('')
onMounted(async()=>{try{const p=(await api.get('/business/policy')).data;prefixes.value=(Array.isArray(p.allowed_prefixes)?p.allowed_prefixes:[]).join(', ');smsLimit.value=p.sms_per_minute}catch{policyMessage.value='Could not load usage controls'}finally{policyLoading.value=false}})
async function policy(){busy.value=true;try{await api.put('/business/policy',{allowed_prefixes:prefixes.value.split(',').map(p=>p.trim()).filter(Boolean),sms_per_minute:smsLimit.value});policyMessage.value='Usage controls saved'}catch{policyMessage.value='Use prefixes such as +44, +91 and an SMS limit from 1 to 120'}finally{busy.value=false}}
const automation=ref({demo_mode:false,ai_enabled:false,key_set:false,missed_call_url_set:false,sms_url_set:false,simulator_enabled:true,dialer_configured:false})
const phoneOnline=ref<boolean|null>(null)
onMounted(async()=>{try{phoneOnline.value=!!((await api.get('/business/accounts')).data.data||[])[0]?.online}catch{phoneOnline.value=null}})
const n8n=()=>automation.value.key_set&&automation.value.missed_call_url_set&&automation.value.sms_url_set
type Tone='ok'|'off'|'warn'|'setup'
const features=()=>{const a=automation.value,c=n8n();return [
 {name:'n8n connection',tone:(c?'ok':(a.key_set||a.missed_call_url_set||a.sms_url_set)?'warn':'setup') as Tone,state:c?'Connected':(a.key_set||a.missed_call_url_set||a.sms_url_set)?'Partly set up':'Not set up',detail:c?'Missed-call text-back and AI webhooks are configured.':'Set GOSIP_AUTOMATION_KEY, GOSIP_N8N_MISSED_CALL_URL and GOSIP_N8N_SMS_URL in Coolify.'},
 {name:'Missed-call text-back',tone:(a.key_set&&a.missed_call_url_set?'ok':'setup') as Tone,state:a.key_set&&a.missed_call_url_set?'Active':'Not set up',detail:'Callers you miss get a text from n8n.'},
 {name:'Demo mode',tone:(a.demo_mode?'warn':'off') as Tone,state:a.demo_mode?'ON — phone will not ring':'Off',detail:'Rejects every call and sends the text-back at once.'},
 {name:'AI replies to SMS',tone:(a.ai_enabled&&a.sms_url_set?'ok':a.sms_url_set?'off':'setup') as Tone,state:a.ai_enabled&&a.sms_url_set?'On':a.sms_url_set?'Off':'Not set up',detail:'Only for people who called.'},
 {name:'Simulator',tone:(a.simulator_enabled?'ok':'off') as Tone,state:a.simulator_enabled?'On':'Off',detail:'Fake calls and texts for testing, never sent to Twilio.'},
 {name:'Browser dialer',tone:(a.dialer_configured?'ok':'setup') as Tone,state:a.dialer_configured?'Set up':'Not set up',detail:a.dialer_configured?'Call and answer from the Dialer page.':'Add TWILIO_API_KEY_SID, TWILIO_API_KEY_SECRET and TWILIO_TWIML_APP_SID in Coolify.'},
 {name:'Linphone',tone:(phoneOnline.value?'ok':'warn') as Tone,state:phoneOnline.value===null?'Unknown':phoneOnline.value?'Signed in':'Not signed in',detail:'The phone app that rings for incoming calls.'},
]}
const toneClass=(t:Tone)=>({ok:'bg-green-600 text-white',off:'bg-gray-600 text-white',warn:'bg-amber-500 text-black',setup:'border border-gray-500 text-gray-400'}[t]),automationMessage=ref(''),automationLoading=ref(true)
onMounted(async()=>{try{automation.value=(await api.get('/business/automation')).data}catch{automationMessage.value='Could not load automation settings'}finally{automationLoading.value=false}})
async function saveAutomation(field:'demo_mode'|'ai_enabled'|'simulator_enabled',value:boolean){automationMessage.value='';try{automation.value=(await api.put('/business/automation',{[field]:value})).data;automationMessage.value='Saved';window.dispatchEvent(new CustomEvent('leadomi:features',{detail:automation.value}))}catch{automationMessage.value='Could not save. Try again.'}}
async function change(){message.value='';if(next.value!==confirm.value){message.value='Passwords do not match';return}busy.value=true;try{await api.put('/me/password',{current_password:current.value,new_password:next.value});message.value='Administrator password changed';current.value='';next.value='';confirm.value=''}catch(e){message.value=(e as {response?:{data?:{error?:{message?:string}}}}).response?.data?.error?.message||'Password could not be changed'}finally{busy.value=false}}
</script>
<template><div class="space-y-6 settings-page"><h1 class="text-2xl font-semibold">Settings</h1>
<div class="settings-card space-y-3"><h2 class="font-semibold">Features status</h2><p class="text-sm text-gray-500">What is set up and switched on right now.</p>
<ul class="divide-y divide-gray-200 dark:divide-gray-700"><li v-for="f in features()" :key="f.name" class="py-2 flex flex-wrap items-center justify-between gap-2"><span class="min-w-0"><span class="font-medium text-sm">{{f.name}}</span><span class="block text-xs text-gray-500">{{f.detail}}</span></span><span :class="['text-xs font-semibold rounded-full px-2 py-0.5 shrink-0',toneClass(f.tone)]">{{automationLoading?'…':f.state}}</span></li></ul></div>
<div class="settings-card space-y-4"><h2 class="font-semibold">Optional features</h2><p v-if="!automationLoading&&!(automation.key_set&&automation.missed_call_url_set&&automation.sms_url_set)" class="text-sm text-amber-500">n8n is not fully connected: set GOSIP_AUTOMATION_KEY, GOSIP_N8N_MISSED_CALL_URL and GOSIP_N8N_SMS_URL in Coolify and redeploy.</p>
<label :class="['flex items-start justify-between gap-4 rounded-lg border p-4 cursor-pointer',automation.demo_mode?'border-amber-500 bg-amber-500/10':'border-gray-300 dark:border-gray-600']"><span><span class="font-medium">Demo mode</span> <span :class="['ml-2 text-xs font-semibold rounded-full px-2 py-0.5',automation.demo_mode?'bg-amber-500 text-black':'bg-gray-600 text-white']">{{automation.demo_mode?'ON':'OFF'}}</span><span class="block text-sm text-gray-500 mt-1">{{automation.demo_mode?'Your phone will NOT ring. Every caller is rejected and gets the text-back straight away — for demos only.':'Normal: the phone rings for 30 seconds; callers get the text-back only if you miss the call.'}}</span></span><span class="relative mt-1 inline-flex shrink-0"><input type="checkbox" role="switch" class="peer sr-only" :checked="automation.demo_mode" :disabled="automationLoading||!automation.key_set||!automation.missed_call_url_set" @change="saveAutomation('demo_mode',($event.target as HTMLInputElement).checked)"/><span aria-hidden="true" class="h-6 w-11 rounded-full bg-gray-400 dark:bg-gray-600 transition-colors peer-checked:bg-amber-500 peer-disabled:opacity-40 peer-focus-visible:ring-2 peer-focus-visible:ring-primary peer-focus-visible:ring-offset-2"></span><span aria-hidden="true" class="pointer-events-none absolute left-0.5 top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform peer-checked:translate-x-5"></span></span></label>
<label :class="['flex items-start justify-between gap-4 rounded-lg border p-4 cursor-pointer',automation.ai_enabled?'border-green-600 bg-green-600/10':'border-gray-300 dark:border-gray-600']"><span><span class="font-medium">AI replies to SMS</span> <span :class="['ml-2 text-xs font-semibold rounded-full px-2 py-0.5',automation.ai_enabled?'bg-green-600 text-white':'bg-gray-600 text-white']">{{automation.ai_enabled?'ON':'OFF'}}</span><span class="block text-sm text-gray-500 mt-1">Only people who called (and got the text-back) are answered by the AI — at most 12 replies, and it stops after a booking. Replies to your outreach go to you. When you reply yourself, the AI pauses for that contact for 24 hours. STOP opts a contact out of all automated texts.</span></span><span class="relative mt-1 inline-flex shrink-0"><input type="checkbox" role="switch" class="peer sr-only" :checked="automation.ai_enabled" :disabled="automationLoading||!automation.key_set||!automation.sms_url_set" @change="saveAutomation('ai_enabled',($event.target as HTMLInputElement).checked)"/><span aria-hidden="true" class="h-6 w-11 rounded-full bg-gray-400 dark:bg-gray-600 transition-colors peer-checked:bg-green-600 peer-disabled:opacity-40 peer-focus-visible:ring-2 peer-focus-visible:ring-primary peer-focus-visible:ring-offset-2"></span><span aria-hidden="true" class="pointer-events-none absolute left-0.5 top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform peer-checked:translate-x-5"></span></span></label>
<label :class="['flex items-start justify-between gap-4 rounded-lg border p-4 cursor-pointer',automation.simulator_enabled?'border-green-600 bg-green-600/10':'border-gray-300 dark:border-gray-600']"><span><span class="font-medium">Simulator</span> <span :class="['ml-2 text-xs font-semibold rounded-full px-2 py-0.5',automation.simulator_enabled?'bg-green-600 text-white':'bg-gray-600 text-white']">{{automation.simulator_enabled?'ON':'OFF'}}</span><span class="block text-sm text-gray-500 mt-1">Test missed calls, texts and the AI with fictional UK numbers (+447700900xxx) without Twilio credits. Turn off to hide the Simulator page.</span></span><span class="relative mt-1 inline-flex shrink-0"><input type="checkbox" role="switch" class="peer sr-only" :checked="automation.simulator_enabled" :disabled="automationLoading" @change="saveAutomation('simulator_enabled',($event.target as HTMLInputElement).checked)"/><span aria-hidden="true" class="h-6 w-11 rounded-full bg-gray-400 dark:bg-gray-600 transition-colors peer-checked:bg-green-600 peer-disabled:opacity-40 peer-focus-visible:ring-2 peer-focus-visible:ring-primary peer-focus-visible:ring-offset-2"></span><span aria-hidden="true" class="pointer-events-none absolute left-0.5 top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform peer-checked:translate-x-5"></span></span></label>
<p class="text-sm" role="status">{{automationMessage}}</p></div><form @submit.prevent="change" class="settings-card space-y-4"><h2 class="font-semibold">Change your administrator password</h2><label class="block">Current password<input v-model="current" type="password" autocomplete="current-password" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">New password<input v-model="next" type="password" autocomplete="new-password" minlength="12" maxlength="72" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">Confirm password<input v-model="confirm" type="password" autocomplete="new-password" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p>{{message}}</p><button :disabled="busy" class="bg-primary text-white rounded px-4 py-2">Change password</button></form><form @submit.prevent="policy" class="settings-card space-y-4"><h2 class="font-semibold">Usage controls</h2><label class="block">Allowed international prefixes<input v-model="prefixes" :disabled="policyLoading" placeholder="+44, +91" class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p class="text-sm text-gray-500">Comma-separated prefixes for outgoing calls and SMS. An empty field allows all destinations. Choose only the countries your team needs.</p><label class="block">SMS per minute per number<input v-model.number="smsLimit" :disabled="policyLoading" type="number" min="1" max="120" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p class="text-sm text-gray-500">Up to two concurrent outgoing calls per SIP user.</p><p>{{policyMessage}}</p><button :disabled="busy||policyLoading" class="bg-primary text-white rounded px-4 py-2">Save usage controls</button></form><div class="settings-card space-y-3"><h2 class="font-semibold">Managed in Coolify</h2><p class="text-sm">Twilio account details, the phone username and the phone password are set as environment variables in Coolify (leadomi-sip → Environment Variables); redeploy after changing them. The phone's number is chosen under Phone Numbers. Unanswered calls ring for 30 seconds, then go to voicemail.</p><RouterLink to="/phone-setup" class="block text-primary">Phone setup instructions →</RouterLink><RouterLink to="/users" class="block text-primary">Manage console administrators →</RouterLink></div></div></template>
